export const code = async (inputs) => {
  const today = new Date().toISOString().split('T')[0];
  const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];

  return {
    sessionId: `analytics_${Date.now()}`,
    dateRange: {
      start: yesterday,
      end: today
    },
    timestamp: new Date().toISOString(),
    platforms: ['facebook', 'twitter', 'instagram', 'linkedin'],
    metrics: {
      engagement: [],
      reach: [],
      clicks: [],
      conversions: []
    }
  };
};

export const code = async (inputs) => {
  const { fetch_facebook_data, fetch_twitter_data, fetch_instagram_data, fetch_linkedin_data } = inputs;

  // Facebook transformation
  const facebookMetrics = {
    platform: 'facebook',
    impressions: fetch_facebook_data.body?.data?.[0]?.values?.[0]?.value || 0,
    engagement: fetch_facebook_data.body?.data?.[1]?.values?.[0]?.value || 0,
    followers: fetch_facebook_data.body?.data?.[2]?.values?.[0]?.value || 0,
    posts: fetch_facebook_data.body?.data?.[3]?.values?.[0]?.value || 0
  };

  // Twitter transformation
  const twitterMetrics = {
    platform: 'twitter',
    impressions: fetch_twitter_data.body?.data?.reduce((sum, tweet) => sum + (tweet.public_metrics?.impression_count || 0), 0) || 0,
    engagement: fetch_twitter_data.body?.data?.reduce((sum, tweet) => sum + (tweet.public_metrics?.like_count || 0) + (tweet.public_metrics?.retweet_count || 0) + (tweet.public_metrics?.reply_count || 0), 0) || 0,
    posts: fetch_twitter_data.body?.meta?.result_count || 0
  };

  // Instagram transformation
  const instagramMetrics = {
    platform: 'instagram',
    impressions: fetch_instagram_data.impressions || 0,
    reach: fetch_instagram_data.reach || 0,
    profile_views: fetch_instagram_data.profile_views || 0,
    website_clicks: fetch_instagram_data.website_clicks || 0,
    followers: fetch_instagram_data.follower_count || 0
  };

  // LinkedIn transformation
  const linkedinMetrics = {
    platform: 'linkedin',
    impressions: fetch_linkedin_data.body?.elements?.[0]?.totalShareStatistics?.impressionCount || 0,
    clicks: fetch_linkedin_data.body?.elements?.[0]?.totalShareStatistics?.clickCount || 0,
    engagement: fetch_linkedin_data.body?.elements?.[0]?.totalShareStatistics?.engagement || 0
  };

  const consolidatedData = {
    sessionId: inputs.init_analytics_session.sessionId,
    timestamp: new Date().toISOString(),
    dateRange: inputs.init_analytics_session.dateRange,
    platforms: {
      facebook: facebookMetrics,
      twitter: twitterMetrics,
      instagram: instagramMetrics,
      linkedin: linkedinMetrics
    },
    totals: {
      impressions: facebookMetrics.impressions + twitterMetrics.impressions + instagramMetrics.impressions + linkedinMetrics.impressions,
      engagement: facebookMetrics.engagement + twitterMetrics.engagement + instagramMetrics.reach + linkedinMetrics.engagement,
      total_followers: facebookMetrics.followers + instagramMetrics.followers
    },
    performance_score: 0 // Calculé dans l'étape suivante
  };

  // Calcul du score de performance
  consolidatedData.performance_score = Math.min(100, Math.round(
    (consolidatedData.totals.engagement / Math.max(consolidatedData.totals.impressions, 1)) * 1000
  ));

  return consolidatedData;
};

export const code = async (inputs) => {
  const data = inputs.transform_social_data;
  const sentiment = inputs.sentiment_analysis;

  // Calculs KPI avancés
  const kpis = {
    engagement_rate: {
      facebook: data.platforms.facebook.engagement / Math.max(data.platforms.facebook.impressions, 1),
      twitter: data.platforms.twitter.engagement / Math.max(data.platforms.twitter.impressions, 1),
      instagram: data.platforms.instagram.reach / Math.max(data.platforms.instagram.impressions, 1),
      linkedin: data.platforms.linkedin.engagement / Math.max(data.platforms.linkedin.impressions, 1)
    },
    reach_efficiency: {
      cost_per_impression: data.totals.impressions > 0 ? 100 / data.totals.impressions : 0,
      organic_reach_score: data.performance_score
    },
    content_performance: {
      sentiment_score: sentiment.overall_score || 0.5,
      sentiment_distribution: sentiment.distribution || { positive: 0.4, neutral: 0.4, negative: 0.2 },
      viral_potential: data.platforms.twitter.engagement / Math.max(data.platforms.twitter.posts, 1)
    },
    growth_indicators: {
      follower_velocity: data.totals.total_followers / 30, // Estimation mensuelle
      engagement_velocity: data.totals.engagement / data.platforms.facebook.posts || 1
    }
  };

  // Détection d'anomalies
  const anomalies = [];

  if (data.performance_score < 10) {
    anomalies.push({ type: 'LOW_PERFORMANCE', message: 'Performance globale faible', severity: 'high' });
  }

  if (sentiment.overall_score < 0.3) {
    anomalies.push({ type: 'NEGATIVE_SENTIMENT', message: 'Sentiment négatif détecté', severity: 'medium' });
  }

  if (data.totals.impressions < 1000) {
    anomalies.push({ type: 'LOW_REACH', message: 'Portée insuffisante', severity: 'medium' });
  }

  return {
    ...data,
    kpis,
    anomalies,
    recommendations: generateRecommendations(kpis, anomalies),
    report_ready: true
  };

  function generateRecommendations(kpis, anomalies) {
    const recommendations = [];

    if (kpis.engagement_rate.instagram > kpis.engagement_rate.facebook) {
      recommendations.push('Concentrez plus d\'efforts sur Instagram (meilleur engagement)');
    }

    if (kpis.content_performance.sentiment_score < 0.4) {
      recommendations.push('Améliorer le tone of voice et la qualité du contenu');
    }

    if (kpis.reach_efficiency.organic_reach_score < 20) {
      recommendations.push('Optimiser les hashtags et horaires de publication');
    }

    return recommendations;
  }
};

