export const code = async (inputs) => {
  const data = inputs.calculate_kpis;
  const timestamp = new Date().toLocaleDateString('fr-FR');

  // Génération du rapport HTML
  const htmlReport = `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="utf-8">
      <title>Rapport Analytics Réseaux Sociaux - ${timestamp}</title>
      <style>
        body { font-family: 'Segoe UI', Arial, sans-serif; margin: 40px; color: #333; }
        .header { text-align: center; border-bottom: 3px solid #4CAF50; padding-bottom: 20px; margin-bottom: 30px; }
        .metric-card { background: #f8f9fa; padding: 20px; margin: 15px 0; border-radius: 8px; border-left: 4px solid #007bff; }
        .platform-section { margin: 20px 0; padding: 15px; border: 1px solid #ddd; border-radius: 5px; }
        .kpi-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
        .alert { padding: 15px; margin: 10px 0; border-radius: 5px; }
        .alert-success { background: #d4edda; border: 1px solid #c3e6cb; }
        .alert-warning { background: #fff3cd; border: 1px solid #ffeaa7; }
        .alert-danger { background: #f8d7da; border: 1px solid #f5c6cb; }
        .recommendations { background: #e7f3ff; padding: 20px; border-radius: 8px; }
        table { width: 100%; border-collapse: collapse; margin: 20px 0; }
        th, td { padding: 12px; text-align: left; border-bottom: 1px solid #ddd; }
        th { background-color: #f2f2f2; font-weight: bold; }
        .score-high { color: #28a745; font-weight: bold; }
        .score-medium { color: #ffc107; font-weight: bold; }
        .score-low { color: #dc3545; font-weight: bold; }
      </style>
    </head>
    <body>
      <div class="header">
        <h1>📊 Rapport Analytics Réseaux Sociaux</h1>
        <p>Période: ${data.dateRange.start} - Généré le ${timestamp}</p>
      </div>

      <div class="metric-card">
        <h2>🎯 Performance Globale</h2>
        <div class="kpi-grid">
          <div>
            <h3>Score Global: <span class="${data.performance_score >= 70 ? 'score-high' : data.performance_score >= 40 ? 'score-medium' : 'score-low'}">${data.performance_score}/100</span></h3>
            <p><strong>Impressions Totales:</strong> ${data.totals.impressions.toLocaleString()}</p>
            <p><strong>Engagement Total:</strong> ${data.totals.engagement.toLocaleString()}</p>
          </div>
          <div>
            <p><strong>Score Sentiment:</strong> ${(data.kpis.content_performance.sentiment_score * 100).toFixed(1)}%</p>
            <p><strong>Followers Totaux:</strong> ${data.totals.total_followers.toLocaleString()}</p>
          </div>
        </div>
      </div>

      <h2>📱 Performance par Plateforme</h2>

      <div class="platform-section">
        <h3>Facebook</h3>
        <table>
          <tr><td>Impressions</td><td>${data.platforms.facebook.impressions.toLocaleString()}</td></tr>
          <tr><td>Engagement</td><td>${data.platforms.facebook.engagement.toLocaleString()}</td></tr>
          <tr><td>Taux d'Engagement</td><td>${(data.kpis.engagement_rate.facebook * 100).toFixed(2)}%</td></tr>
        </table>
      </div>

      <div class="platform-section">
        <h3>Twitter</h3>
        <table>
          <tr><td>Impressions</td><td>${data.platforms.twitter.impressions.toLocaleString()}</td></tr>
          <tr><td>Engagement</td><td>${data.platforms.twitter.engagement.toLocaleString()}</td></tr>
          <tr><td>Posts</td><td>${data.platforms.twitter.posts}</td></tr>
        </table>
      </div>

      <div class="platform-section">
        <h3>Instagram</h3>
        <table>
          <tr><td>Impressions</td><td>${data.platforms.instagram.impressions.toLocaleString()}</td></tr>
          <tr><td>Portée</td><td>${data.platforms.instagram.reach.toLocaleString()}</td></tr>
          <tr><td>Vues Profil</td><td>${data.platforms.instagram.profile_views.toLocaleString()}</td></tr>
          <tr><td>Clics Site Web</td><td>${data.platforms.instagram.website_clicks}</td></tr>
        </table>
      </div>

      <div class="platform-section">
        <h3>LinkedIn</h3>
        <table>
          <tr><td>Impressions</td><td>${data.platforms.linkedin.impressions.toLocaleString()}</td></tr>
          <tr><td>Clics</td><td>${data.platforms.linkedin.clicks}</td></tr>
          <tr><td>Engagement</td><td>${data.platforms.linkedin.engagement}</td></tr>
        </table>
      </div>

      ${data.anomalies.length > 0 ? `
        <div class="alert alert-${data.anomalies.some(a => a.severity === 'high') ? 'danger' : 'warning'}">
          <h3>⚠️ Anomalies Détectées</h3>
          <ul>
            ${data.anomalies.map(anomaly => `<li><strong>${anomaly.type}:</strong> ${anomaly.message}</li>`).join('')}
          </ul>
        </div>
      ` : '<div class="alert alert-success"><h3>✅ Aucune anomalie détectée</h3></div>'}

      <div class="recommendations">
        <h3>💡 Recommandations</h3>
        <ul>
          ${data.recommendations.map(rec => `<li>${rec}</li>`).join('')}
        </ul>
      </div>

      <div style="margin-top: 40px; text-align: center; color: #666; font-size: 12px;">
        <p>Rapport généré automatiquement par ActivePieces Social Analytics - ${new Date().toISOString()}</p>
      </div>
    </body>
    </html>
  `;

  return {
    htmlReport,
    fileName: `social_analytics_report_${data.dateRange.start.replace(/-/g, '')}.html`,
    summary: {
      score: data.performance_score,
      total_impressions: data.totals.impressions,
      total_engagement: data.totals.engagement,
      anomalies_count: data.anomalies.length,
      top_platform: getBestPlatform(data.platforms)
    }
  };

  function getBestPlatform(platforms) {
    let best = { name: '', score: 0 };

    Object.entries(platforms).forEach(([name, metrics]) => {
      const score = metrics.engagement + metrics.impressions;
      if (score > best.score) {
        best = { name, score };
      }
    });

    return best.name;
  }
};
